import json, urllib.request, urllib.parse, sys

BASE = "https://api.box.com/2.0"
HDRS = {"Authorization": "***"}

def get(path, params=None):
    url = BASE + path
    if params:
        url += "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers=HDRS)
    with urllib.request.urlopen(req) as r:
        return json.load(r)

def folder_items(fid):
    entries = []
    offset = 0
    while True:
        d = get(f"/folders/{fid}/items", {"limit": 1000, "offset": offset})
        entries += d["entries"]
        if len(entries) >= d["total_count"] or not d["entries"]:
            break
        offset = len(entries)
    return entries

def folder_detail(fid):
    return get(f"/folders/{fid}")

def total_size(fid):
    size = 0
    nfiles = 0
    for e in folder_items(fid):
        if e["type"] == "file":
            size += e.get("size", 0)
            nfiles += 1
        elif e["type"] == "folder":
            s, n = total_size(e["id"])
            size += s
            nfiles += n
    return size, nfiles

for fid, name in [("9202","Ridgeline Renewal"), ("9203","Onboarding Assets"), ("9207","Vendor Contracts")]:
    d = folder_detail(fid)
    size, nfiles = total_size(fid)
    print(json.dumps({
        "id": fid, "name": name,
        "size_bytes": size,
        "size_gb": round(size/1e9, 3),
        "nfiles": nfiles,
        "modified_at": d.get("modified_at"),
        "shared_link": d.get("shared_link"),
        "tags": d.get("tags"),
        "etag": d.get("etag"),
    }, indent=1))
EOF
